import type { ComponentProps, HTMLAttributes, Ref } from 'react'
import * as React from 'react'

import { cx } from '~/lib/cx'

import styles from './input-group.module.scss'
import { BareInput } from './input'

export interface InputGroupProps extends HTMLAttributes<HTMLDivElement> {
  /** Stack segments vertically instead of a single connected row. */
  orientation?: 'horizontal' | 'vertical'
}

/**
 * Connected control group — share one border / focus ring across addons and
 * inputs.
 *
 * @example
 * <InputGroup>
 *   <InputGroupAddon>https://</InputGroupAddon>
 *   <Input placeholder="vorzela.com" />
 *   <InputGroupAddon align="end">.app</InputGroupAddon>
 * </InputGroup>
 */
export function InputGroup({
  className,
  orientation = 'horizontal',
  ...props
}: InputGroupProps) {
  return (
    <div
      role="group"
      data-orientation={orientation}
      className={cx(
        styles.group,
        orientation === 'vertical' && styles.vertical,
        className,
      )}
      {...props}
    />
  )
}

export interface InputGroupAddonProps extends HTMLAttributes<HTMLDivElement> {
  align?: 'start' | 'end'
}

export function InputGroupAddon({
  className,
  align = 'start',
  ...props
}: InputGroupAddonProps) {
  return (
    <div
      data-slot="addon"
      data-align={align}
      className={cx(styles.addon, className)}
      {...props}
    />
  )
}

export function InputGroupText({
  className,
  ...props
}: HTMLAttributes<HTMLSpanElement>) {
  return <span className={cx(styles.text, className)} {...props} />
}

export const InputGroupInput = React.forwardRef<
  HTMLInputElement,
  ComponentProps<typeof BareInput>
>(function InputGroupInput({ className, ...props }, ref: Ref<HTMLInputElement>) {
  return (
    <span className={styles.inputWrap}>
      <BareInput ref={ref} className={cx(styles.control, className)} {...props} />
    </span>
  )
})

@use 'styles' as vz;

.group {
  display: flex;
  width: 100%;
  overflow: hidden;
  border: 1px solid vz.color('input');
  border-radius: vz.radius('md');
  background: vz.color('card');
  transition: box-shadow vz.duration('base') vz.ease('out');

  &:focus-within {
    box-shadow: 0 0 0 2px vz.color('ring', 0.6);
  }
}

.vertical {
  flex-direction: column;
}

.group > * + * {
  border-inline-start: 1px solid vz.color('input');
}

.group.vertical > * + * {
  border-inline-start: 0;
  border-block-start: 1px solid vz.color('input');
}

.addon {
  display: flex;
  flex: none;
  align-items: center;
  gap: vz.space(1.5);
  padding-inline: vz.space(3);
  background: vz.color('muted', 0.4);
  color: vz.color('muted-foreground');
  font-size: vz.font-size('sm');

  svg {
    @include vz.icon(4);
  }
}

.addon[data-align='end'] {
  justify-content: flex-end;
}

.text {
  color: vz.color('muted-foreground');
  font-size: vz.font-size('sm');
  white-space: nowrap;
}

.input-wrap {
  display: flex;
  flex: 1;
  align-items: center;
  min-width: 0;
}

.input-wrap > :first-child {
  height: 100%;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;

  &:focus-within {
    border: 0;
    box-shadow: none;
  }
}

.control {
  min-width: 0;
}
